            if (!Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
                Files.createFile(storedRulesFile.toPath());
            }
            if (!isDirectRegularFile(storedRulesFile.toPath())) {
                throw new StoreInitializationFailedException(String.format(
                        "Violation store index %s must be a regular file directly in the store folder",
                        storedRulesFile.getAbsolutePath()));
            }
        } catch (StoreInitializationFailedException e) {
            throw e;
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void ensureStoreFolder() throws IOException {
        if (!Files.exists(storeFolderPath, LinkOption.NOFOLLOW_LINKS)) {
            if (!storeFolder.mkdirs() && !storeFolder.isDirectory()) {
                throw new IOException("Could not create store folder " + storeFolder);
            }
        }
        if (!Files.isDirectory(storeFolderPath, LinkOption.NOFOLLOW_LINKS)) {
            throw new IOException("Store path is not a directory: " + storeFolder);
        }
    }

    private boolean isDirectRegularFile(Path path) {
        if (!Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)) {
            return false;
        }
        return storeFolderPath.equals(path.toAbsolutePath().normalize().getParent());
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storedRules) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storedRules) {
            String description = ensureUnixLineBreaks(rule.getDescription());
            String existingFileName = storedRules.getProperty(description);
            if (violations.isEmpty() && existingFileName == null) {
                return;
            }
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                forgetRule(description, existingFileName);
                return;
            }

            String fileName = existingFileName != null ? existingFileName : createFileName(description);
            Path target = writableTarget(fileName, existingFileName != null);
            FileSnapshot snapshot = FileSnapshot.capture(target);
            byte[] oldIndex = storedRules.fileBytes();
            try {
                writeFile(target, serializeViolations(violations));
                if (existingFileName == null) {
                    storedRules.put(description, fileName);
                    storedRules.syncFileSystem();
                }
            } catch (RuntimeException e) {
                restoreSnapshot(target, snapshot);
                storedRules.restore(oldIndex);
                storedRules.restoreFileSystem(oldIndex);
                throw e;
            }
        }
    }

    private String createFileName(String description) {
        String result = ruleViolationFileNameStrategy.createRuleFileName(description);
        if (result == null || result.isEmpty()) {
            throw new StoreUpdateFailedException(String.format(
                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
        }
        return result;
    }

    private Path writableTarget(String fileName, boolean existingEntry) {
        Path candidate = storeFolderPath.resolve(fileName).normalize();
        if (!isDirectPath(candidate) || STORED_RULES_FILE_NAME.equals(fileName)) {
            throw new StoreUpdateFailedException(String.format(
                    "Refusing to write violation file '%s': it is not a safe file directly in the store folder", fileName));
        }

        try {
            if (Files.exists(candidate, LinkOption.NOFOLLOW_LINKS)) {
                if (!existingEntry) {
                    throw new IOException("a file already exists and is not recorded by this rule");
                }
                if (Files.isSymbolicLink(candidate)) {
                    Path resolved = candidate.toRealPath();
                    if (isStoredRulesPath(resolved) || !isDirectPath(resolved)
                            || !Files.isRegularFile(resolved, LinkOption.NOFOLLOW_LINKS)) {
                        throw new IOException("symbolic link does not resolve to a regular file in the store folder");
                    }
                    return resolved;
                }
                if (!Files.isRegularFile(candidate, LinkOption.NOFOLLOW_LINKS)) {
                    throw new IOException("target is not a regular file");
                }
                Path resolved = candidate.toRealPath();
                if (isStoredRulesPath(resolved)) {
                    throw new IOException("target is the violation store index");
                }
                return resolved;
            }
            return candidate;
        } catch (IOException e) {
            throw new StoreUpdateFailedException(String.format(
                    "Refusing to write violation file '%s': %s", fileName, e.getMessage()));
        }
    }

    private boolean isDirectPath(Path path) {
        return storeFolderPath.equals(path.toAbsolutePath().normalize().getParent())
                && !storeFolderPath.equals(path.toAbsolutePath().normalize());
    }

    private boolean isStoredRulesPath(Path path) {
        return storeFolderPath.resolve(STORED_RULES_FILE_NAME).equals(path.toAbsolutePath().normalize());
    }

    private byte[] serializeViolations(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        return builder.toString().getBytes(UTF_8);
    }

    private void writeFile(Path target, byte[] content) {
        Path temporary = null;
        try {
            temporary = Files.createTempFile(storeFolderPath, ".archunit-violation-", ".tmp");
            Files.write(temporary, content, StandardOpenOption.TRUNCATE_EXISTING);
            moveReplacing(temporary, target);
        } catch (IOException e) {
            if (temporary != null) {
                deleteQuietly(temporary);
            }
            throw new StoreUpdateFailedException(e);
        }
    }

    private void restoreSnapshot(Path target, FileSnapshot snapshot) {
        try {
            if (snapshot.exists) {
                writeFile(target, snapshot.content);
            } else {
                deleteQuietly(target);
            }
        } catch (RuntimeException ignored) {
            log.warn("Could not restore violation file {} after a failed store update", target);
        }
