+    private Path writableTarget(String fileName, boolean existingEntry) {
+        Path candidate = storeFolderPath.resolve(fileName).normalize();
+        if (!isDirectPath(candidate) || STORED_RULES_FILE_NAME.equals(fileName)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to write violation file '%s': it is not a safe file directly in the store folder", fileName));
+        }
+
+        try {
+            if (Files.exists(candidate, LinkOption.NOFOLLOW_LINKS)) {
+                if (Files.isSymbolicLink(candidate)) {
+                    Path resolved = candidate.toRealPath();
+                    if (!isDirectPath(resolved) || !Files.isRegularFile(resolved, LinkOption.NOFOLLOW_LINKS)) {
+                        throw new IOException("symbolic link does not resolve to a regular file in the store folder");
+                    }
+                    return resolved;
+                }
+                if (!Files.isRegularFile(candidate, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new IOException("target is not a regular file");
