+    private Path safeDeletionTarget(String fileName) {
+        if (STORED_RULES_FILE_NAME.equals(fileName)) {
+            throw new StoreUpdateFailedException("Refusing to delete the violation store index");
+        }
+        Path path = storeFolderPath.resolve(fileName).normalize();
+        if (!isDirectPath(path)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to delete violation file '%s': it is outside the store folder", fileName));
+        }
+        try {
+            if (Files.isSymbolicLink(path)) {
+                if (!Files.exists(path)) {
+                    return path;
+                }
+                Path resolved = path.toRealPath();
+                if (!isDirectPath(resolved) || !Files.isRegularFile(resolved, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new IOException("symbolic link does not resolve to a regular file in the store folder");
+                }
+                return resolved;
+            }
+            if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
+                return path;
+            }
+            if (!Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)) {
+                throw new IOException("target is not a regular file");
+            }
+            return path.toRealPath();
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Refusing to delete violation file '%s': %s", fileName, e.getMessage()));
+        }
+    }
