+    private void deleteNamedFile(String fileName, Path resolved) {
+        Path named = storeFolderPath.resolve(fileName).normalize();
+        try {
+            if (Files.isSymbolicLink(named)) {
+                Files.deleteIfExists(named);
+                if (!named.equals(resolved)) {
+                    Files.deleteIfExists(resolved);
