+            if (!description.equals(otherDescription) && fileName.equals(storedRules.getProperty(otherDescription))) {
+                return true;
+            }
+        }
+        try {
+            Path target = storeFolderPath.resolve(fileName).normalize();
+            if (!Files.exists(target, LinkOption.NOFOLLOW_LINKS)) {
+                return false;
+            }
+            Path resolved = target.toRealPath();
+            for (String otherDescription : storedRules.keys()) {
+                if (description.equals(otherDescription)) {
+                    continue;
+                }
+                String otherFileName = storedRules.getProperty(otherDescription);
+                Path other = storeFolderPath.resolve(otherFileName).normalize();
+                if (Files.exists(other, LinkOption.NOFOLLOW_LINKS) && Files.isSameFile(resolved, other.toRealPath())) {
+                    return true;
