+    private IntegrityReport inspectIntegrity() {
+        List<Entry> entries = new ArrayList<>();
+        for (String description : storedRules.keys()) {
+            String fileName = storedRules.getProperty(description);
+            entries.add(new Entry(description, fileName, storeFolderPath));
+        }
+
+        Map<String, List<Entry>> entriesByName = groupByName(entries);
+        Map<String, List<Entry>> entriesByDerivedName = new HashMap<>();
+        for (Entry entry : entries) {
+            if (!randomFileNames) {
+                entry.derivedName = requiredFileName(entry.description);
+                entriesByDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+            }
+        }
+
+        for (Entry entry : entries) {
+            entry.inspectFile();
+            entry.shared = entriesByName.get(entry.fileName).size() > 1;
+        }
+        for (Entry entry : entries) {
+            if (entry.resolvedPath != null) {
+                for (Entry other : entries) {
+                    if (entry == other || other.resolvedPath == null) {
+                        continue;
+                    }
+                    if (sameFile(entry.resolvedPath, other.resolvedPath)) {
+                        entry.shared = true;
+                        other.shared = true;
+                    }
+                }
+            }
+            if (entry.derivedName != null) {
+                entry.misplaced = !entry.fileName.equals(entry.derivedName);
+                entry.colliding = entriesByDerivedName.get(entry.derivedName).size() > 1;
+                if (entry.misplaced && (entry.derivedName.equals(STORED_RULES_FILE_NAME)
+                        || entriesByName.containsKey(entry.derivedName)
+                        || derivedPathNamesSomething(entry.derivedName))) {
+                    entry.occupied = true;
+                }
+            }
+            if (STORED_RULES_FILE_NAME.equals(entry.fileName)) {
+                entry.occupied = true;
+            }
+        }
