+    private String requiredFileName(String description) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not derive a violation file name for rule '%s'", description), e);
+        }
+        if (result == null || result.isEmpty()) {
+            throw new StoreInitializationFailedException(String.format(
+                    "RuleViolationFileNameStrategy returned no name for rule '%s'", description));
+        }
+        return result;
+    }
