+    private Map<String, List<Entry>> groupByName(List<Entry> entries) {
+        Map<String, List<Entry>> result = new HashMap<>();
+        for (Entry entry : entries) {
+            result.computeIfAbsent(entry.fileName, ignored -> new ArrayList<>()).add(entry);
+        }
+        return result;
+    }
