+    private boolean derivedPathNamesSomething(String fileName) {
+        Path candidate = storeFolderPath.resolve(fileName).normalize();
+        if (!isDirectPath(candidate) || STORED_RULES_FILE_NAME.equals(fileName)) {
+            return true;
+        }
+        return Files.exists(candidate, LinkOption.NOFOLLOW_LINKS);
+    }
