+    private List<Path> findUnownedFiles(List<Entry> entries) {
+        List<Path> result = new ArrayList<>();
+        try (DirectoryStream<Path> files = Files.newDirectoryStream(storeFolderPath)) {
+            for (Path file : files) {
+                if (file.getFileName().toString().equals(STORED_RULES_FILE_NAME)
+                        || !Files.isRegularFile(file, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (Entry entry : entries) {
+                    if (entry.resolvedPath != null && sameFile(file, entry.resolvedPath)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    result.add(file);
+                }
+            }
