+    private void repair(IntegrityReport report) {
+        boolean indexChanged = false;
+        for (Entry entry : report.entries) {
+            if (entry.shared || entry.occupied && STORED_RULES_FILE_NAME.equals(entry.fileName)) {
+                continue;
+            }
+            if (entry.broken) {
+                storedRules.remove(entry.description);
+                indexChanged = true;
+            } else if (entry.resolved) {
+                deleteResolvedEntry(entry);
+                storedRules.remove(entry.description);
+                indexChanged = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveMisplacedEntry(entry);
+                storedRules.put(entry.description, entry.derivedName);
+                indexChanged = true;
+            }
+        }
+        if (indexChanged) {
+            storedRules.syncFileSystem();
+        }
+    }
+
+    private void deleteResolvedEntry(Entry entry) {
+        try {
+            Path named = storeFolderPath.resolve(entry.fileName).normalize();
+            if (Files.isSymbolicLink(named)) {
+                Files.deleteIfExists(named);
+                if (entry.resolvedPath != null && !named.equals(entry.resolvedPath)) {
+                    Files.deleteIfExists(entry.resolvedPath);
+                }
+            } else if (entry.resolvedPath != null) {
+                Files.deleteIfExists(entry.resolvedPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not remove resolved violation file '%s'", entry.fileName), e);
+        }
+    }
+
+    private void moveMisplacedEntry(Entry entry) {
