+        if (!isDirectPath(destination) || Files.exists(destination, LinkOption.NOFOLLOW_LINKS)) {
+            return;
+        }
+        try {
+            Path named = storeFolderPath.resolve(entry.fileName).normalize();
+            Files.move(entry.resolvedPath, destination, StandardCopyOption.ATOMIC_MOVE);
+            if (Files.isSymbolicLink(named)) {
+                Files.deleteIfExists(named);
+            }
+        } catch (AtomicMoveNotSupportedException e) {
+            try {
+                Files.move(entry.resolvedPath, destination);
+                Path named = storeFolderPath.resolve(entry.fileName).normalize();
+                if (Files.isSymbolicLink(named)) {
