+                if (!Files.exists(namedPath, LinkOption.NOFOLLOW_LINKS)) {
+                    broken = true;
+                    return;
+                }
+                resolvedPath = namedPath.toRealPath();
+                broken = !isDirectRegularFile(resolvedPath);
